from lib import *
S = SS('k21')
F1 = [['openssl', '私钥 + CSR(CN=jane,O=devs)'], ['kubectl create csr', 'Pending'], ['没人批准', '没人签发']]
F2 = [['approve', 'Approved'], ['controller-manager 签名者', '用集群 CA 签'], ['status.certificate', '几乎立刻出现'], ['证书', 'CN=jane,O=devs']]
F3 = [['证书 → kubeconfig', 'user=jane'], ['whoami', 'jane + devs'], ['RBAC', '先 Forbidden'], ['绑定 view', '才能 get pods']]
F4 = [['deny', 'Denied,没有证书'], ['陌生的 signerName', '批准了也没人签'], ['usages 不符', 'Failed: SignerValidationFailure']]
PANELS = [('f', 'flow', '证书签发'), ('t', 'term', '实测输出'), ('kv', 'kv', '要点')]
steps = [
    step("openssl 生成 RSA 2048 密钥和 CSR(CN=jane,O=devs),提交 CertificateSigningRequest jane(signerName=kubernetes.io/kube-apiserver-client,expirationSeconds=3600,usages=[client auth]):创建成功,status.conditions 为空、certificate 为空,spec.username=kubernetes-admin,kubectl get csr 的 CONDITION 是 Pending,REQUESTEDDURATION 是 60m;等 3 秒仍然没有证书——没人批准就没人签发。", f=fl(F1, cur=[1], mark=[2], done=[0]), t=tl(S(1), mark=lidx(S(1), 'Pending', '仍然是'), done=lidx(S(1), 'created')), kv=KV([['CSR 对象', '只是个申请,私钥不会交给集群'], ['谁提交的', 'spec.username / groups 记录了请求者'], ['不批准', '一直 Pending']], ['CSR 对象'])),
    step("kubectl certificate approve jane 之后,controller-manager 的签名者几乎立刻把证书写回 status.certificate。证书:subject=O=devs, CN=jane;issuer=CN=kubernetes(集群 CA);Extended Key Usage 只有 TLS Web Client Authentication;notAfter - notBefore = 3900 秒——请求的是 3600 秒,notBefore 比签发时刻早了约 300 秒(往前回拨 5 分钟防时钟偏差)。", f=fl(F2, cur=[1, 2], done=[0, 3]), t=tl(S(2), mark=lidx(S(2), 'subject=', 'notAfter - notBefore'), done=lidx(S(2), 'issuer=', 'approved')), kv=KV([['身份', '证书里的 CN 是用户名,O 是组'], ['有效期', '请求的秒数 + 回拨的 300 秒'], ['签发者', '集群 CA(CN=kubernetes)']], ['有效期'])),
    step("把证书和私钥写进独立的 kubeconfig:kubectl auth whoami → jane,groups [devs, system:authenticated];get pods -n k21 → Forbidden(User \"jane\" cannot list resource \"pods\");给组 devs 绑定 ClusterRole view(RoleBinding 在 k21)后 → No resources found;同一个用户看 default 命名空间仍是 Forbidden;auth can-i delete pods → no;kubectl get users → the server doesn't have a resource type \"users\"。", f=fl(F3, cur=[3], mark=[2], done=[0, 1]), t=tl(S(3), mark=lidx(S(3), 'Forbidden', 'can-i'), done=lidx(S(3), 'whoami', 'No resources found')), kv=KV([['证书只证明“你是谁”', '权限要 RBAC 另给'], ['没有 User 对象', '用户只存在于证书里'], ['按组授权', 'O=devs 就是组 devs']], ['没有 User 对象'])),
    step("几种失败:kubectl certificate deny bob → Denied,没有证书;signerName=example.com/my-signer 的 CSR 被 approve 后 5 秒仍无证书(没有组件负责这个签名者);kube-apiserver-client 却申请 usages=[server auth] 的 dave 创建时没被拒绝,approve 之后出现 Failed 条件 SignerValidationFailure:invalid usage for client certificate: server auth,同样没有证书。", f=fl(F4, cur=[2], mark=[0, 1]), t=tl(S(4), mark=lidx(S(4), 'Denied', 'SignerValidationFailure', 'example.com/my-signer'), done=lidx(S(4), 'kubectl get csr jane')), kv=KV([['Denied / Failed', '都不会有证书'], ['approve ≠ 签发', '还要有对应的签名者去签'], ['内置签名者', '只管 kubernetes.io/* 几种']], ['approve ≠ 签发'])),
]
A = mkartk('k21', 21, 'Kubernetes,CSR,CertificateSigningRequest,用户证书,kubeconfig,RBAC,真实验证,动画演示',
    '在 kind 集群里走完 kubectl 用户证书的签发:openssl 生成密钥和 CSR(CN=jane,O=devs),CertificateSigningRequest 在批准前一直 Pending;approve 后签名者几乎立刻签出证书(issuer=CN=kubernetes,有效期 = 请求的 3600 秒 + 回拨 300 秒);用它建 kubeconfig,whoami 得到 jane 与组 devs,没有 RBAC 时 Forbidden,绑定 view 后可以 get pods;deny、陌生的 signerName 与用途不符(SignerValidationFailure)都得不到证书。',
    '“给新同事发一个 kubectl 账号”在 Kubernetes 里是怎么做的?集群里没有 User 对象,身份就写在证书里。这篇把用户证书从私钥、CSR、批准、签发到写进 kubeconfig、被 RBAC 拦下再放行的全过程真跑了一遍,并看了几种得不到证书的情形。',
    [('3900 秒', '请求 expirationSeconds=3600 的证书实际的 notAfter - notBefore(notBefore 回拨了 300 秒)'), ('jane + devs', '用这张证书的 kubeconfig 执行 kubectl auth whoami 得到的用户与组(来自 CN 与 O)'), ('SignerValidationFailure', 'kube-apiserver-client 的 CSR 申请了 server auth 用途、被批准后出现的 Failed 条件')],
    [('提交 CSR', '<p>私钥留在用户手里,只有 CSR 交给集群:<code>CertificateSigningRequest</code> 里是 base64 的 CSR、<code>signerName: kubernetes.io/kube-apiserver-client</code>、<code>usages: [client auth]</code> 和 <code>expirationSeconds: 3600</code>。创建后它只是个对象,<code>status</code> 里什么都没有,<code>kubectl get csr</code> 显示 <code>Pending</code>;<code>spec.username</code> 记着是谁提交的。没人批准,等多久都没有证书。</p>'),
     ('批准与签发', '<p><code>kubectl certificate approve jane</code> 之后,controller-manager 里的签名者用集群 CA 签出证书,几乎立刻出现在 <code>status.certificate</code>。证书里 <code>subject=O=devs, CN=jane</code>、<code>issuer=CN=kubernetes</code>、只有 <code>TLS Web Client Authentication</code> 用途。有效期是 3900 秒,不是请求的 3600:<code>notBefore</code> 比签发时刻早了约 300 秒,防止时钟不同步导致刚签的证书“还没生效”。</p>'),
     ('用证书当用户', '<p>把证书和私钥写进独立的 kubeconfig:<code>whoami</code> 得到 <code>jane</code>,组是 <code>devs</code>(证书的 <code>O</code>)和 <code>system:authenticated</code>。证书只证明身份,权限一点没有:<code>get pods</code> 是 <code>Forbidden</code>。给组 <code>devs</code> 在 k21 命名空间绑定 <code>view</code> 之后才能列出 Pod,到 <code>default</code> 命名空间仍然被拒,<code>can-i delete pods</code> 是 <code>no</code>。<code>kubectl get users</code> 报 <code>the server doesn\'t have a resource type "users"</code>——集群里没有 User 对象,所以要撤销一个用户只能等证书过期或撤销它的权限。</p>'),
     ('得不到证书的几种情形', '<p><code>deny</code> 的 CSR 变成 <code>Denied</code>,没有证书;<code>signerName</code> 是 <code>example.com/my-signer</code> 的 CSR 即使被 approve 也没有人签(内置签名者只处理 <code>kubernetes.io/*</code>);<code>kube-apiserver-client</code> 却申请 <code>server auth</code> 用途,创建时能通过,<code>approve</code> 之后才出现 <code>Failed: SignerValidationFailure — invalid usage for client certificate: server auth</code>。排查“批准了却没有证书”先看 conditions。</p>')],
    steps,
    [ENV_K + '。三节点 kind 集群 kx-main(Kubernetes v1.37.0,kubeadm 默认的签名设置);密钥与 CSR 由宿主机 openssl 生成,证书内容用 openssl x509 解析;用户的 kubeconfig 是单独写在实验目录里的文件,不碰 ~/.kube;RBAC 绑定的是内置 ClusterRole view(RoleBinding 在 k21 命名空间);实验后删除了所有 CSR、RoleBinding 和临时文件;每种情形各一次',
     '没有验证:CSR 的自动清理(已签发 1 小时后、Pending 24 小时后被清理);--cluster-signing-duration 对有效期上限的约束(只验证了请求 3600 秒的情形);kubernetes.io/kubelet-serving 与 kube-apiserver-client-kubelet 的自动批准;证书轮换与吊销(Kubernetes 没有 CRL 机制);ECDSA 密钥;O=system:masters 之类的高权限组被批准的后果'],
    '证书签发', PANELS)
